import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int n=sc.nextInt();Map<String,List<String>>g=new LinkedHashMap<>();for(int i=0;i<n;i++){String w=sc.next();char[]c=w.toCharArray();Arrays.sort(c);String k=new String(c);g.computeIfAbsent(k,x->new ArrayList<>()).add(w);}for(List<String>v:g.values()){StringJoiner sj=new StringJoiner(" ");for(String s:v)sj.add(s);System.out.println(sj);}}}
